def backtrack(index, right, buckets, sub_sum, ans, memo):
    if index == right:
        # 所有桶的值都已经达到 sub_sum
        return all(bucket == sub_sum for bucket in buckets)

    # 使用 memo 来缓存已经尝试过的状态
    state = tuple(buckets)
    if state in memo:
        return False
    memo.add(state)

    for i in range(len(buckets)):
        # 剪枝：避免重复运算
        if i > 0 and buckets[i] == buckets[i - 1]:
            continue

        if buckets[i] + ans[index] > sub_sum:
            continue

        # 递归
        buckets[i] += ans[index]
        if backtrack(index + 1, right, buckets, sub_sum, ans, memo):
            return True
        # 回溯
        buckets[i] -= ans[index]

    return False
​
def can_partition(ans, n, total_sum):
    if total_sum % n != 0:
        return False

    sub_sum = total_sum // n
    if ans[0] > sub_sum:
        return False
​
    begin_index = 0
    while begin_index < len(ans) and ans[begin_index] == sub_sum:
        n -= 1
        begin_index += 1
​
    if n == 0:
        return True

    buckets = [0] * n
    memo = set()  # 用于缓存已经遍历的桶状态
    return backtrack(begin_index, len(ans), buckets, sub_sum, ans, memo)
​
def main():
    n = int(input())
    ans = list(map(int, input().split()))
    total_sum = sum(ans)

    # 降序排序
    ans.sort(reverse=True)

    # 从大到小枚举获取MVP人数
    while n != 1:
        if can_partition(ans, n, total_sum):
            break
        n -= 1

    print(total_sum // n)
