package main
​
import (
    "fmt"
    "sort"
)
​
func cmp(x, y int) bool {
    return x > y
}
​
func backtrack(index, right int, buckets []int, subSum int, ans []int) bool {
    if index == right {
        for _, bucket := range buckets {
            if bucket != subSum {
                return false
            }
        }
        return true
    }
​
    for i := 0; i < len(buckets); i++ {
        // 剪枝，避免重复运算
        if i > 0 && buckets[i] == buckets[i-1] {
            continue
        }
​
        if buckets[i]+ans[index] > subSum {
            continue
        }
​
        // 递归
        buckets[i] += ans[index]
        if backtrack(index+1, right, buckets, subSum, ans) {
            return true
        }
        // 回溯
        buckets[i] -= ans[index]
    }
​
    return false
}
​
func canPartition(ans []int, n, totalSum int) bool {
    // 如果不能整除，直接返回 false
    if totalSum%n != 0 {
        return false
    }
​
    // 每个人应该得到的分数
    subSum := totalSum / n
    size := len(ans)
​
    // 如果最大的得分大于 subSum，直接返回 false
    if ans[0] > subSum {
        return false
    }
​
    beginIndex := 0
​
    // 预处理数据，减少计算量
    for beginIndex < size && ans[beginIndex] == subSum {
        n--
        beginIndex++
    }
​
    if n == 0 {
        return true
    }
​
    buckets := make([]int, n)
    return backtrack(beginIndex, size, buckets, subSum, ans)
}
​
func main() {
    var n int
    fmt.Scan(&n) // 输入人数
    ans := make([]int, n)
    totalSum := 0
​
    // 输入所有的得分并计算总分
    for i := 0; i < n; i++ {
        fmt.Scan(&ans[i])
        totalSum += ans[i]
    }
​
    // 将得分按降序排序
    sort.Slice(ans, func(i, j int) bool {
        return cmp(ans[i], ans[j])
    })
​
    // 从大到小枚举获取 MVP 的人数
    for n != 1 {
        if canPartition(ans, n, totalSum) {
            break
        }
        n--
    }
​
    // 输出每个人的分数
    fmt.Println(totalSum / n)
}
